::Legacy.getEnemyTooltipMode <- function() {
    try {
        if (::Legacy.Mod == null) return "Hide everything";
        local s = ::Legacy.Mod.ModSettings.getSetting("Legacy_EnemyTooltip");
        if (s == null) return "Hide everything";
        return s.getValue();
    } catch (e) {
        return "Hide everything";
    }
};

