::Legacy.getEnemyTooltipMode <- function() {
    try {
        if (::Legacy.Mod == null) return "Off";
        local s = ::Legacy.Mod.ModSettings.getSetting("Legacy_EnemyTooltip");
        if (s == null) return "Off";
        return s.getValue();
    } catch (e) {
        return "Off";
    }
};
